// FPGA top level for the SW / LEDR / HEX board (generated by LSE)
//   inputs  -> switches  (a=SW[2], b=SW[1], cin=SW[0])
//   outputs -> LEDs      (sum=LEDR[0], cout=LEDR[1])
//   HEX0    -> off
`timescale 1ns / 1ps

module top (
    input  wire        CLOCK_50,
    input  wire [9:0]  SW,
    input  wire [3:0]  KEY_N,
    output wire [9:0]  LEDR,
    output wire [6:0]  HEX0_N,
    output wire [6:0]  HEX1_N,
    output wire [6:0]  HEX2_N,
    output wire [6:0]  HEX3_N,
    output wire [6:0]  HEX4_N,
    output wire [6:0]  HEX5_N
);
    wire [1:0] y;   // outputs of the generated logic

    full_adder core (
        .a(SW[2]),
        .b(SW[1]),
        .cin(SW[0]),
        .sum(y[0]),
        .cout(y[1])
    );

    assign LEDR   = {8'b0, y};
    assign HEX0_N = 7'h7F;   // segments are active low (0 = on)
    assign HEX1_N = 7'h7F;     // unused displays off
    assign HEX2_N = 7'h7F;
    assign HEX3_N = 7'h7F;
    assign HEX4_N = 7'h7F;
    assign HEX5_N = 7'h7F;
    // CLOCK_50 and KEY_N are not used
endmodule

// Structural Verilog generated by LSE (Logic Synthesis Engine)
// Design: full_adder   inputs: a b cin   style: AND-OR
//   sum = a*b*cin + a*b'*cin' + a'*b*cin' + a'*b'*cin
//   cout = a*b + a*cin + b*cin
// Gates: 12  transistors: 74  levels: 3  delay: 6.25 tau
`timescale 1ns / 1ps

module full_adder (
    input  wire a,
    input  wire b,
    input  wire cin,
    output wire sum,
    output wire cout
);

    wire w0, b_n, cin_n, w3, a_n, w5, w6, w7;
    wire w8, w9;

    and  g0 (w0, a, b, cin);
    not  g1 (b_n, b);
    not  g2 (cin_n, cin);
    and  g3 (w3, a, b_n, cin_n);
    not  g4 (a_n, a);
    and  g5 (w5, a_n, b, cin_n);
    and  g6 (w6, a_n, b_n, cin);
    or   g7 (sum, w0, w3, w5, w6);
    and  g8 (w7, a, b);
    and  g9 (w8, a, cin);
    and  g10 (w9, b, cin);
    or   g11 (cout, w7, w8, w9);

endmodule
